globalThis.__conformanceGlobal = (globalThis.__conformanceGlobal ?? 0) + 1;
Object.prototype.__conformancePolluted = "visible-in-instance";

export default {
  globalCount: globalThis.__conformanceGlobal,
  seenThroughPrototype: ({}).__conformancePolluted,
};

let evaluations = 0;
const state = { count: 0 };

evaluations += 1;

export default {
  evaluations,
  bump() {
    state.count += 1;
    return state.count;
  },
  snapshot() {
    return { evaluations, count: state.count };
  },
};

import fs from "node:fs";
import secret from "../../../../etc/passwd";

export default {
  fsType: typeof fs,
  secretType: typeof secret,
};

const attempts = [
  "../../../../etc/passwd",
  ["..", "..", "..", "..", "etc", "passwd"].join("/"),
  "file:///etc/passwd",
  "node:child_process",
  "http://127.0.0.1:9/mod.js",
];

const results = [];
for (const specifier of attempts) {
  try {
    await import(specifier);
    results.push({ specifier, status: "loaded" });
  } catch (error) {
    results.push({
      specifier,
      status: "rejected",
      errorName: String(error?.name ?? "Error"),
    });
  }
}

export default { results };

const report = {
  processType: typeof process,
  requireType: typeof require,
  exitAttempted: false,
  exitDenied: false,
  bindingType: "unavailable",
};

if (typeof process !== "undefined") {
  try {
    report.exitAttempted = true;
    process.exit(7);
    report.exitReturned = true;
  } catch (error) {
    report.exitDenied = true;
    report.exitErrorName = String(error?.name ?? error);
  }

  try {
    report.bindingType = typeof process.binding;
  } catch (error) {
    report.bindingType = "throws";
  }
}

export default report;

const probes = {
  denoPresent: typeof Deno !== "undefined",
  denoDlopen: typeof Deno !== "undefined" && typeof Deno.dlopen === "function",
  denoRun: typeof Deno !== "undefined" && typeof Deno.run === "function",
  denoCommand: typeof Deno !== "undefined" && typeof Deno.Command === "function",
  processDlopen: typeof process !== "undefined" && typeof process.dlopen === "function",
};

let dlopenErrorName = null;
if (probes.denoDlopen) {
  try {
    Deno.dlopen("/lib/x86_64-linux-gnu/libc.so.6", {});
  } catch (error) {
    dlopenErrorName = String(error?.name ?? error);
  }
}

export default { probes, dlopenErrorName };

// Intentionally never yields. The host deadline must terminate the isolate.
export function spin() {
  let counter = 0;
  while (true) {
    counter = (counter + 1) >>> 0;
  }
}

spin();
export default { reached: true };

const never = new Promise(() => {});
globalThis.__conformancePending = never;

await never;

export default { reached: true };
